    ["270cb3d"] = "Para a sua especialização é o que mais conta.",
    ["759646f"] = "DPS da arma corpo a corpo:",
    ["620e128"] = "mas a sua especialização não bate com essa arma e não o usa.",
    ["f8fc3c4"] = "que para a sua especialização conta.",
    ["704cc42"] = "Armadura:",
    ["4842b23"] = "As outras diferenças (armadura, dano...) não contam para a sua especialização.",
    ["46e81de"] = "Os atributos que contam para você são iguais.",
    ["984170a"] = "Para a sua especialização neste espaço o que mais conta é: %s.",
    ["a6ac637"] = "Com os mesmos atributos, mais armadura é melhor.",
    ["d39c34f"] = "Com os mesmos atributos, menos armadura é pior.",
    ["8878fa5"] = "A rotação Beast Mastery do guia (subida 1-60): sem corpo a corpo; Hunter's Mark e Serpent Sting como abertura, falcões (Summon Hawk) a partir do 25, Aimed Shot e Arcane Shot, Multi-Shot e Explosive Trap contra vários monstros. As habilidades de recarga longa (Bestial Wrath, Rapid Fire, raciais) ficam fora da rotação, para usar à mão. Criada pelo BuildBeast.",
    ["3fcb6ff"] = "Rotação do BuildBeast para subir de nível de 1 a 60, tirada do guia: o Hekili escolhe entre elas só as habilidades que você já aprendeu. Criada pelo BuildBeast.",
    ["f7219d4"] = "para esta especialização o BuildBeast ainda não tem rotação própria: o Hekili usa a dele.",
    ["f23ecca"] = "O Hekili não está carregado.",
    ["2ec553f"] = "Não consegui criar a prioridade no Hekili.",
    ["9e1f59d"] = "O Hekili já usa a prioridade: %s",
    ["bbf6862"] = "prioridade do Hekili definida: %s",
    ["3f1c97f"] = "O Hekili não aceitou a prioridade.",
    ["511ff29"] = "brilho dos botões:",
    ["c172ef4"] = "ligado",
    ["72960be"] = "desligado",
    ["969f47a"] = "Ouro = usar agora, azul = a próxima.",
    ["2850cfb"] = "sombreado das recargas:",
    ["c4ad91d"] = "visível",
    ["aba8815"] = "oculto",
    ["babe955"] = "números de recarga nos botões:",
    ["48983fc"] = "ligados",
    ["3424735"] = "desligados",
    ["8b823dc"] = "O Zygor não está pronto.",
    ["7496082"] = "marcas de talentos do Zygor:",
    ["1b9f260"] = "Abra de novo a janela de talentos.",
    ["7c4161e"] = "Você troca de alvo sem interromper o Auto Shot.",
    ["3ddfa3b"] = "O pet ataca o alvo que você marca com Hunter's Mark.",
    ["d00e00c"] = "Um único botão para as habilidades corpo a corpo, para quando você é atacado.",
    ["458bcf6"] = "Alterna Mongoose Bite e Counterattack com um botão só, depois de uma esquiva ou aparo.",
    ["7e3322d"] = "Lança a habilidade e inicia o ataque automático, mesmo antes de engajar. Você pode pôr outra habilidade no lugar de Heroic Strike. É preciso ter raiva suficiente.",
    ["4215a24"] = "Sunder Armor no inimigo sob o cursor, sem selecioná-lo.",
    ["fade647"] = "Blessing of Protection no aliado sob o cursor (se não houver, no seu alvo).",
    ["0ea3265"] = "Blessing of Freedom no aliado sob o cursor.",
    ["474ed6a"] = "Cleanse no aliado sob o cursor.",
    ["dd398c9"] = "Invoca o Advanced Target Dummy no cursor e lança Blessing of Protection nele: aperte duas vezes, sem recarga global ativa.",
    ["ad171ca"] = "Divine Shield em você; apertando de novo você o remove na hora. Aperte duas vezes, sem recarga global ativa.",
    ["8b1f0a2"] = "Inicia o ataque automático e lança Holy Strike. Não ponha em Holy Shield.",
    ["39da0a5"] = "Power Word: Shield no cursor, senão em você.",
    ["885b4fd"] = "Greater Heal no cursor, senão no alvo, senão em você.",
    ["f6044e4"] = "Interrompe a conjuração em curso e lança de novo Greater Heal: para quando outro curandeiro já curou esse alvo.",
    ["73afb8f"] = "Inner Focus e logo em seguida Prayer of Healing: para emergências.",
    ["91996ef"] = "Dispel Magic esperto: remove magias nocivas dos aliados e benéficas dos inimigos.",
    ["b32d1df"] = "Prayer of Mending no cursor, senão no alvo, senão em você.",
    ["4e5454e"] = "Interrompe a conjuração e usa Shadow Word: Death num monstro quase morto que foge ou num totem.",
    ["4b2ea52"] = "Aplica Deadly Poison na arma da mão principal; o ícone mostra a duração.",
    ["73d1f2d"] = "Aplica Instant Poison na arma da mão secundária; o ícone mostra a duração.",
    ["672d6cc"] = "Pick Pocket como abertura, depois Garrote (você pode trocar por Cheap Shot ou Ambush).",
    ["c2da64b"] = "Manda pet e personagem atacarem com um botão só: assim você não fica parado enquanto sobe de nível.",
    ["8833bc9"] = "Como BB Attacco, mas lança também Stormstrike (no lugar da macro anterior).",
    ["79e760c"] = "Totemic Projection onde está o cursor.",
    ["93ec012"] = "Nature's Swiftness e logo em seguida Healing Wave no cursor: cura de emergência instantânea. Tire [@mouseover] se não quiser a cura pelo cursor.",
    ["ddfe74e"] = "Polymorph no alvo em foco; se não houver ou não for inimigo, no alvo atual.",
    ["425c144"] = "Usa os dois berloques com um botão só (espaços 13 e 14).",
    ["23fc3c4"] = "Combustion junto com os dois berloques.",
    ["6d5d784"] = "Manda o pet atacar e depois o deixa passivo, como no guia.",
    ["3b9d855"] = "Amplify Curse e Bane of Agony juntos: para a abertura ou quando Amplify Curse está pronta.",
    ["67eb4db"] = "Drain Life que você pode apertar várias vezes sem interromper.",
    ["c24583f"] = "Corruption no alvo sob o cursor: para pôr DOTs em vários inimigos. Troque Corruption por outro DOT.",
    ["de046d0"] = "Fel Domination e logo em seguida Imp: para chamar o pet de volta depois que ele morre, ou para a build de execução.",
    ["0da2d35"] = "Fel Domination e logo em seguida Succubus: para chamar o pet de volta depois que ele morre.",
    ["701f8c9"] = "Bane of Havoc no alvo sob o cursor.",
    ["6177927"] = "Immolate no foco (o alvo de Bane of Havoc).",
    ["687eb32"] = "Corruption no foco.",
    ["dfc9982"] = "Bane of Doom no foco.",
    ["f14c9c9"] = "Bane of Agony no foco.",
    ["37f2591"] = "Hurricane que não se interrompe sozinho se você apertar o botão durante a conjuração.",
    ["e041704"] = "Moonfire no cursor: para pôr DOTs em vários inimigos (troque por Insect Swarm para o outro).",
    ["11b387e"] = "Feral Charge (gato) e depois Prowl, se você ainda não estiver furtivo.",
    ["9bca5ec"] = "Muda de forma para se livrar de raízes e lentidões: de urso para gato, de gato para gato.",
    ["38e0846"] = "Um botão só: Aquatic Form na água, Travel Form ao ar livre, senão Cat Form.",
    ["53406a7"] = "Entra em Dire Bear Form uma vez só, sem sair se você apertar de novo.",
    ["b18da61"] = "Growl no foco, depois no cursor, depois no alvo.",
    ["beb6029"] = "Nature's Swiftness e logo em seguida Healing Touch: cura de emergência instantânea (sai da forma e interrompe a conjuração).",
    ["8c5c182"] = "Não é possível criar macros em combate: tente depois.",
    ["e3c93a8"] = "Macros: %d criadas, %d atualizadas%s. Abra-as com /macro e arraste-as para as barras.",
    ["99effc3"] = "%d não criadas (você já tem 18 macros do personagem)",
    ["530c645"] = "Não há macros para esta especialização.",
    ["1e74c8f"] = "O BuildBeast vai criar %s macros para o seu personagem:\n%s\n\nSe já existirem, ele as atualiza. Depois você as arrasta para as barras.",
    ["d8354a3"] = "Criar",
    ["160009a"] = "Cancelar",
    ["054716f"] = "Guerreiro",
    ["3e76e85"] = "Paladino",
    ["69c8129"] = "Caçador",
    ["dd6c053"] = "Ladino",
    ["3a3f441"] = "Sacerdote",
    ["fabeb14"] = "Xamã",
    ["a5a0a92"] = "Mago",
    ["8b0635d"] = "Bruxo",
    ["3d8e8ed"] = "Druida",
    ["ce774d9"] = "SIM",
    ["c2f3f48"] = "NÃO",
    ["672c529"] = "PARECIDO",
    ["656ff24"] = "Bear Form, Growl, Maul (missão de classe), Nature's Grasp, Demoralizing Roar",
    ["50d1ea3"] = "Bash; missão para Cure Poison",
    ["2290f2a"] = "Swipe; missão para Aquatic Form",
    ["227f378"] = "Faerie Fire (agora também nas formas), Hibernate",
    ["469f184"] = "Cat Form (missão), Prowl, Claw, Rip, Shred, Starfire, Rebirth, Omen of Clarity",
    ["eda7053"] = "Mark of the Wild em você. Abra com Wrath e continue lançando. Quando o mana estiver baixo, termine o monstro com a arma, assim o mana volta. Cure-se com Healing Touch entre os combates.",
    ["3d495a9"] = "Mantenha Mark of the Wild e Thorns em você e coloque Rejuvenation antes de engajar. Abra com Wrath, adicione Moonfire e continue com Wrath. Numa zona cheia abra com Moonfire, que é instantâneo.",
    ["bb21cc8"] = "A missão de classe dá a você Bear Form, Growl e Maul. Nature's Grasp prende o próximo monstro que te bater; Demoralizing Roar é para a forma de urso.",
    ["a9ba21f"] = "Enrage dá raiva na hora e mais em 10 segundos, mas diminui a sua armadura.",
    ["9c7f3ca"] = "Feral é a especialização de gato e urso, e a que sobe com mais fluidez: Prowl e Dash levam você de um objetivo ao outro e quase nunca você para por causa do mana. Em Bear Form: Mark of the Wild e Thorns em você, e deixe a raiva dos seus golpes pagar Maul, que soma dano ao golpe seguinte. Contra vários monstros Demoralizing Roar para enfraquecê-los.",
    ["ce230c2"] = "Em Bear Form: Enrage antes do pull (a perda de armadura pesa menos), Faerie Fire baixa a armadura do monstro, Swipe é o preenchimento e Maul gasta a raiva que sobra. Com vários monstros Demoralizing Roar primeiro, depois Swipe.",
    ["78a0920"] = "Cat Form: primeiro Mark of the Wild e Thorns. Abra de Prowl com Shred (Prowl leva você para trás do monstro), depois Faerie Fire, depois Claw para acumular pontos de combo ou Shred quando estiver atrás. Com quatro ou mais pontos de combo, Rip se o monstro viver o bastante. Bear Form continua melhor contra vários monstros: a forma de gato não tem nada que atinja mais de um.",
    ["540175c"] = "Rake: abra de Prowl com Shred, Faerie Fire, depois Rake e mantenha o sangramento dele sempre ativo num monstro que viva o bastante; depois Claw ou Shred por trás. Com 4 ou mais pontos: Rip se o monstro viver, Ferocious Bite para terminar.",
    ["87e3251"] = "Lacerate (urso): um sangramento que se acumula até 5 vezes; contra um monstro só é o seu preenchimento, e Maul gasta a raiva que sobra. Com vários monstros Demoralizing Roar e depois Swipe. Blood Frenzy: em urso cada crítico dá 5 de raiva, em gato um crítico com uma habilidade de pontos de combo dá mais um.",
    ["25dc320"] = "Predatory Discipline: Ferocious Bite ainda ganha dano com a energia extra, mas não a gasta.",
    ["042c952"] = "Ravage: abra de Prowl com Ravage (você precisa estar atrás do monstro), depois Faerie Fire, Rake com o sangramento sempre ativo, depois Claw ou Shred por trás; com 4 ou mais pontos Rip ou Ferocious Bite para terminar. Poised tira 10 de energia do seu primeiro golpe se você começa com a energia cheia.",
    ["4560b4d"] = "Dire Bear Form: Enrage antes do pull, Faerie Fire, Primal Bite a cada recarga (uma mordida forte com 6 segundos de recarga e muita ameaça), Lacerate no meio contra um monstro só e Maul para gastar o resto; com vários monstros Demoralizing Roar e Swipe no lugar de Lacerate.",
    ["ff10d54"] = "Gato: Shifting Power quando você tem menos de 50 de energia (transforma mana em 40 de energia, 8 segundos de recarga).",
    ["0d8ecd7"] = "O Feral quer antes de tudo o dano por segundo da arma, porque a sua forma se baseia nele, e a velocidade da arma não conta. Depois Acerto (Hit), crítico, Agilidade e Força.",
    ["4a841e3"] = "Guardian é o urso: usa o mesmo plano de talentos do Feral. Bear Form com Mark of the Wild e Thorns em você; a raiva dos golpes paga Maul. Contra vários monstros Demoralizing Roar.",
    ["7b551a8"] = "Enrage antes do pull, Faerie Fire no monstro, Swipe como preenchimento e Maul com a raiva que sobra. Com vários monstros Demoralizing Roar depois Swipe.",
    ["af4c8fb"] = "Lacerate é o seu preenchimento contra um monstro só (acumula até 5 vezes); Maul gasta a raiva que sobra. Com vários monstros Demoralizing Roar e Swipe.",
    ["5213241"] = "Dire Bear Form: Enrage antes do pull, Faerie Fire, Primal Bite a cada recarga (6 segundos, muita ameaça), Lacerate no meio contra um monstro só e Maul para o resto; com vários monstros Demoralizing Roar e Swipe no lugar de Lacerate.",
    ["fc61247"] = "O urso quer o dano por segundo da arma (a velocidade não conta), depois Acerto (Hit), crítico, Agilidade e Força. Para a forma de urso servem também Força e poder mágico, e o Vigor conta mais se você tanka.",
    ["25acd2a"] = "Balance e Restoration começam iguais: Improved Wrath (meio segundo a menos de lançamento e metade do mana) e Nature's Focus. Balance começa devagar, mas acelera quando Insect Swarm se soma a Moonfire em cada monstro.",
    ["9c1fb9f"] = "Mark of the Wild e Thorns em você, Rejuvenation antes de engajar. Abra com Wrath ou com Moonfire se a zona estiver cheia. Moonfire e Insect Swarm no monstro (um DOT que também diminui a chance de ele acertar), depois Wrath. Regrowth se precisar de cura, Nature's Grasp antes que chegue um segundo monstro.",
    ["7f51b3b"] = "Moonfire e Insect Swarm em cada monstro que você enfrenta, depois Wrath. Com três ou mais monstros, Hurricane.",
    ["c845919"] = "Com três ou mais monstros, Barkskin e depois Hurricane.",
    ["d66aa4c"] = "Eclipse: cada Wrath tira meio segundo dos seus dois Starfire seguintes, assim Starfire entra finalmente na rotação: um Wrath seguido de dois Starfire.",
    ["7e94c11"] = "Moonkin Form: muita armadura, 3% de crítico para o grupo e Omen of Clarity dispara o dobro de vezes; você não pode lançar curas enquanto está nela, então saia para Regrowth e volte. Rotação: Moonfire e Insect Swarm, depois um Wrath e dois Starfire.",
    ["ef6797a"] = "Para Balance e Restoration vem primeiro o poder mágico, depois Intelecto, crítico e Espírito; Restoration acrescenta o poder de cura no 60. Um cajado de conjurador pode vir de uma missão de facção.",
    ["a91a8ac"] = "Restoration é a mais lenta para subir, porque curar não mata monstros: você pode subir como Balance ou Feral e mesmo assim curar as masmorras.",
    ["7a2110b"] = "Mark of the Wild e Thorns em você, Rejuvenation antes de engajar. Abra com Wrath ou Moonfire numa zona cheia, depois Moonfire e Insect Swarm no monstro e Wrath. Regrowth se precisar de cura, Nature's Grasp antes que chegue um segundo monstro.",
    ["937f66e"] = "Swiftmend: cura instantânea em quem tem o seu Rejuvenation ou Regrowth. Quando você leva dano, Swiftmend no seu Rejuvenation e depois Regrowth se precisar de mais. Com três ou mais monstros, Hurricane.",
    ["2061d06"] = "Nature's Swiftness: o seu próximo feitiço de natureza é instantâneo. Deixe fora da rotação, para o momento em que você precisa de uma cura grande agora.",
    ["1164b95"] = "Wild Growth: cura o alvo e o grupo dele em 7 segundos, mais forte no início: em grupo quando mais de um está ferido.",
    ["8f8a34a"] = "Aspect of the Hawk, domar o pet (missão de classe: Tame Beast, Call Pet, Feed Pet, Revive Pet)",
    ["2b3db50"] = "Auto Shot começa sozinho: fique parado meio segundo antes de cada tiro e deixe o monstro chegar. Raptor Strike se ele alcançar você. A menos de 8 metros os tiros à distância não funcionam.",
    ["9329f10"] = "Acrescente Serpent Sting como abertura, só em monstros que duram: se ele morrer em poucos segundos o dano é desperdiçado.",
    ["d2b7bf1"] = "Hunter's Mark antes do pull, depois Serpent Sting. Arcane Shot quando tiver mana.",
    ["85f72cd"] = "O centro é o Auto Shot, com Arcane Shot quando tiver mana. Antes do pull Hunter's Mark, depois Serpent Sting como abertura. Enquanto o monstro corre até você, Concussive Shot o desacelera; Raptor Strike se ele alcançar você.",
    ["71067ff"] = "Você tem o pet: mande-o na frente por alguns segundos, depois Serpent Sting. Mantenha sempre Aspect of the Hawk e alimente o pet. Concussive Shot se o monstro se virar contra você, Raptor Strike como último recurso.",
    ["bb6f64b"] = "Rapid Fire (+40% de velocidade de ataque por 15 segundos) fica fora da rotação: guarde-o para o pull que precisar.",
    ["ebe54cf"] = "O centro é Aimed Shot sempre que estiver pronto (2 segundos de lançamento, 6 segundos de recarga compartilhados com Multi-Shot), com Auto Shot nos vazios. Antes do pull Hunter's Mark, pet na frente, depois Serpent Sting. Arcane Shot quando tiver mana. Se o monstro alcançar você: Disengage. Com vários monstros: Multi-Shot no lugar de Aimed Shot.",
    ["c943332"] = "O centro são os falcões (Summon Hawk): cada falcão dura 18 segundos, dois podem ficar fora; invoque um novo quando um dos dois expirar. Depois Aimed Shot quando pronto e Auto Shot nos vazios. Arcane Shot usa a mesma recarga dos falcões, então espere depois deles. O resto como antes.",
    ["ab9f050"] = "Acrescente Intimidation: se o monstro se virar contra você, atordoa e dá ameaça ao pet; Disengage quando não estiver pronta. Com vários monstros: Explosive Trap primeiro, depois Multi-Shot na recarga de Aimed Shot.",
    ["bf06335"] = "Bestial Wrath (2 minutos) e Volley ficam fora da rotação: use-os à mão nos pulls perigosos ou com grupos grandes. A partir do 42 quase todos os pontos vão para Marksmanship: a rotação não muda.",
    ["e096af7"] = "Beast Mastery atira de longe: contam o DPS da arma à distância e depois a Agilidade. A arma corpo a corpo serve só pelos atributos.",
    ["b35c3c9"] = "O centro é Aimed Shot sempre que estiver pronto, com Auto Shot nos vazios. Depois da vantagem do pet, o primeiro tiro deve ser o mais forte: com Rapid Killing à espera é Aimed Shot. Antes do pull Hunter's Mark e pet na frente; Serpent Sting em cada monstro, porque se ele morrer com Serpent Sting o seu próximo tiro em 20 segundos faz até 20% mais. Arcane Shot quando tiver mana. Se o monstro alcançar você: Disengage. Com vários monstros: Multi-Shot no lugar de Aimed Shot.",
    ["cf4e14e"] = "Antes do pull também Trueshot Aura, além de Hunter's Mark.",
    ["51e16cf"] = "Sniper Shot é o seu tiro mais forte: 4 segundos de lançamento, 15 segundos de recarga, até 45 metros, e por 10 segundos os seus três tiros seguintes alcançam 10 metros a mais. Use como primeiro tiro depois da vantagem do pet quando houver tempo para o lançamento, melhor com Rapid Killing à espera; senão Aimed Shot. Com vários monstros: Explosive Trap primeiro, depois Multi-Shot na recarga de Aimed Shot.",
    ["c8aaa16"] = "O centro são os falcões (Summon Hawk): um novo sempre que um dos dois expirar. Depois Aimed Shot quando pronto e Auto Shot nos vazios; Sniper Shot como primeiro tiro se houver tempo. Arcane Shot espera depois dos falcões.",
    ["1fe9ee6"] = "Marksmanship atira de longe: contam o DPS da arma à distância (em igualdade, melhor uma mais lenta com golpes grandes, porque Aimed Shot se baseia num golpe da arma) e a Agilidade. Com Careful Aim o Intelecto também conta como poder de ataque, além do mana. A arma corpo a corpo serve só pelos atributos.",
    ["184fc61"] = "Survival luta em dois lugares. À distância: Multi-Shot sempre que estiver pronto (é instantâneo e divide a recarga com Aimed Shot, então você quase não usa Aimed Shot), mais Serpent Sting, Arcane Shot e Auto Shot. Em corpo a corpo: Immolation Trap, depois Raptor Strike (instantâneo, 6 segundos de recarga) e Mongoose Bite depois de uma esquiva. Hunter's Mark antes do pull e o pet entra primeiro.",
    ["d85837a"] = "Strider Kick: um chute com todo o dano da arma que deixa você 30% mais rápido por 3 segundos: é a tecla que encerra o corpo a corpo e leva você de volta à distância. Em corpo a corpo primeiro Immolation Trap, Mongoose Bite quando usável, Raptor Strike. À distância Multi-Shot quando pronto, Serpent Sting, Arcane Shot, Auto Shot. Com vários monstros Explosive Trap toma o lugar de Immolation Trap, porque uma só recarga vale para todas as armadilhas.",
    ["e7233e1"] = "Com Lacerating Strikes cada Mongoose Bite deixa um sangramento igual a 40% do dano do golpe, em 21 segundos.",
    ["10bfe36"] = "Survival atira mas também bate com a arma corpo a corpo (Raptor Strike e Strider Kick se baseiam no dano dela): ajuda uma de duas mãos lenta. Depois conta a Agilidade. A partir do 49 Careful Aim faz o Intelecto servir também como poder de ataque.",
    ["0718298"] = "Blink, Evocation, Mana Shield, Blizzard, Fire Ward, teletransporte para duas capitais (e Arcane Blast para Arcane e Fire)",
    ["ad986c1"] = "Conjure Mana Agate (a primeira gema de mana)",
    ["3e67dd9"] = "Ice Armor; missão de classe (a varinha Ice Fury)",
    ["3ddbf7c"] = "Frostfire Bolt, primeiros portais",
    ["3d9e7fb"] = "Mantenha sempre Arcane Intellect e um feitiço de armadura (por enquanto Frost Armor). A regeneração de mana para por 5 segundos depois de cada feitiço que custa mana: um monstro quase morto não vale um lançamento completo. Por volta do nível 5 pegue uma varinha (um Encantador faz a Lesser Magic Wand, a Greater Magic Wand a partir do 13): até os talentos ela pode causar tanto dano quanto os seus feitiços ou mais e não gasta mana.",
    ["2991425"] = "Abra com Frostbolt à distância máxima, assim o monstro chega desacelerado. Continue lançando enquanto ele se aproxima, depois Fire Blast para terminar e a varinha para o que sobrar.",
    ["5d6b9a7"] = "Frost Nova congela tudo ao seu redor: o dano a quebra, então você pode recuar e continuar lançando. Se o monstro chegar ao corpo a corpo: Frost Nova e recue.",
    ["11f2d67"] = "Com Missile Barrage: abra de longe com Frostbolt (Arcane e Frost) ou Fireball (Fire), continue lançando e quando o proc disparar lance Arcane Missiles: viram uma saraivada grátis. Missile Barrage é o talento que mais poupa mana enquanto você sobe.",
    ["b985201"] = "Evocation é uma canalização de 8 segundos que devolve boa parte do mana. Blink na recarga enquanto corre faz você chegar cerca de um quinto mais rápido. A pedra de regresso é melhor usada para a zona de missões, porque o teletransporte já leva você a uma capital.",
    ["a601e53"] = "Arcane Blast: cada lançamento dá dano mágico igual a 12% do seu Intelecto, até 4 cargas que duram 18 segundos; cada carga faz o próximo lançamento custar 100% a mais. Frostbolt de longe, depois Arcane Blast de uma a três vezes até Missile Barrage disparar, então Arcane Missiles. Deixe as cargas expirarem em vez de chegar a quatro. Gaste Clear Casting num Arcane Blast carregado. Em corpo a corpo: Frost Nova e recue. Fire Blast para terminar e a varinha.",
    ["e55eb73"] = "Arcane Wrath: um golpe pesado com 6 segundos de recarga (o dano extra vale 5% do seu mana máximo). Frostbolt de longe, depois Arcane Wrath, Arcane Blast de uma a três vezes até Missile Barrage e Arcane Missiles; Frost Nova quando ele se aproximar, de novo Arcane Wrath, depois Fire Blast e a varinha para matar. Deixe as cargas expirarem ou o custo crescente esvazia você; Clear Casting só num Arcane Blast carregado ou num Arcane Wrath, nunca num feitiço barato.",
    ["65a5bf0"] = "Presence of Mind: o seu próximo feitiço com lançamento abaixo de 10 segundos é instantâneo.",
    ["c51b464"] = "Arcane Power: +30% de dano por 15 segundos, ao custo de +30% de mana.",
    ["dfc4101"] = "Abra com Pyroblast ou Frostbolt de longe, depois Arcane Wrath. Arcane Blast de uma a três vezes até Missile Barrage, depois os mísseis. A partir do 58 Fire Blast na recarga e Pyroblast quando Heating Up chegar a 3 cargas.",
    ["9226a40"] = "Para cada especialização o poder mágico vem primeiro, porque os seus feitiços crescem muito com ele. O Intelecto aumenta o mana e um pouco o crítico; o Espírito reduz as pausas para beber, e para Arcane conta muito porque gasta mana rápido.",
    ["ebbbb02"] = "Fireball de longe. Um ou dois Arcane Blast até Missile Barrage disparar, depois os mísseis. Fire Blast na recarga. Um monstro com pouca vida não precisa ficar à distância: deixe-o bater em você algumas vezes, abaixo de 15% a varinha termina.",
    ["9e5f918"] = "Scorch preenche os vazios mesmo com o monstro em cima.",
    ["ab79a6b"] = "Abra com Frostfire Bolt de longe, depois um ou dois Arcane Blast até Missile Barrage disparar e os mísseis. Fire Blast na recarga, Scorch para preencher os vazios, a varinha para os últimos 15%.",
    ["bece8ec"] = "Pyroblast e Heating Up: cada crítico não periódico de Fireball, Frostfire Bolt, Fire Blast ou Scorch deixa o seu próximo Pyroblast um quarto mais rápido, até 3 cargas, e Fire Blast adiciona uma carga a cada dano. Lance Pyroblast quando Heating Up chegar a 3 cargas.",
    ["196edb9"] = "Para cada especialização o poder mágico vem primeiro. O Intelecto aumenta o mana e um pouco o crítico; o Espírito reduz as pausas para beber.",
    ["38bc29a"] = "Frost começa com Precision: dois pontos levam a chance de acertar monstros do seu nível a 100%.",
    ["c690916"] = "Frostbite: os seus efeitos de gelo têm 15% de chance de congelar o alvo por 5 segundos. Ice Lance (a partir do 27): contra um alvo congelado faz 300% a mais, com 8 segundos de recarga compartilhados com Fire Blast.",
    ["1f1ed9a"] = "Frostbolt de longe, e continue lançando enquanto o monstro chega. Quando Frostbite congela o alvo: um Frostbolt com Ice Lance logo atrás; se Ice Lance não estiver pronta, Cone of Cold. Em corpo a corpo: Frost Nova e recue, depois Frostbolt e Ice Lance no monstro congelado. Missile Barrage: lance os mísseis, ou guarde para o próximo monstro se este estiver quase morto. Fire Blast ou a varinha para um monstro com pouca vida que não esteja congelado.",
    ["2e43c7c"] = "Com Fingers of Frost os seus próximos dois feitiços tratam o alvo como congelado: o primeiro num Frostbolt, o segundo num Frostbolt com Ice Lance (ou com Cone of Cold se Ice Lance ainda não estiver pronta). O ponto forte dela está nos 30: depois de Shatter um alvo congelado sofre os seus golpes mais duros.",
    ["cecd125"] = "Ice Barrier primeiro, e lance de novo quando o minuto acabar: além do escudo dá 15% a mais de dano de gelo por um minuto.",
    ["959453a"] = "Winter's Chill: Frostbolt e Ice Lance a acumulam no alvo até 5 vezes, e o próximo Cone of Cold faz 20% a mais por carga.",
    ["5a9d3eb"] = "Redemption (missão de classe)",
    ["3d343ad"] = "Seal of Command (talento Retribution), Seal of Justice",
    ["32b558d"] = "Dupla especialização e montaria",
    ["38d0905"] = "Antes do pull Blessing of Might e Devotion Aura. Depois três passos: Seal of Righteousness, Judgment enquanto você corre para o monstro, Holy Strike. Depois, Judgment e Holy Strike sempre que estiverem prontos, e renove o selo só quando estiver para acabar (Judgment não o consome mais e fica fora da recarga global). O mana também é a sua cura: se o próximo golpe mata o monstro, pule a tecla. Se terminar um combate com mana sobrando, transforme em vida com Holy Light. Em perigo: primeiro Divine Protection em você, depois cure.",
    ["f580de7"] = "Consecration quando você enfrenta vários inimigos ou tem mana sobrando: custa mais que Judgment e Holy Strike juntos e precisa de 8 segundos para fazer todo o seu dano. Exorcism em cada morto-vivo ou demônio, até a 30 metros.",
    ["2ea2c89"] = "Acrescente Hammer of Wrath: termina inimigos abaixo de 20% de vida.",
    ["c8d4778"] = "Retribution e Protection começam na mesma árvore com quase os mesmos talentos. No lugar de Deflection (5% de aparo) você pode escolher Benediction: todas as habilidades instantâneas custam 10% menos mana, e Consecration fica mais fácil de pagar.",
    ["a81d5b1"] = "Com Seal of Command: Blessing of Kings ou Might e Retribution Aura. Num monstro que dura: primeiro o Judgment de Seal of the Crusader (o monstro sofre mais dano sagrado), depois passe para Seal of Command se tiver uma arma lenta; com uma arma rápida ou muito dano mágico é melhor Seal of Righteousness. Depois Judgment e Holy Strike a cada recarga. Truque: o Judgment de Seal of Command faz quase o dobro contra um alvo atordoado, então abra com Hammer of Justice e depois Judgment.",
    ["733e5e6"] = "Sacred Arbiter: Holy Strike bate 20% mais forte e renova todo Judgment no alvo, inclusive os de outros paladinos.",
    ["a01f90a"] = "Champion of the Light transforma até 60% do seu Intelecto em dano mágico: o equipamento com poder mágico fica ainda melhor. No 40 Unsealed Wrath: os golpes guardam uma cópia do selo ativo (até 3), e trocar de selo volta a compensar.",
    ["5f3698b"] = "A arma é o mais importante: idealmente com poder mágico e muito dano. Com Seal of Command as armas lentas e pesadas são as melhores (Holy Strike e o selo fazem mais dano). No resto primeiro Força ou poder de ataque, depois Vigor, depois poder mágico.",
    ["4c063de"] = "Holy começa como Retribution: os primeiros 12 pontos (até o nível 21) vão para Retribution, para ter mais eficiência de mana e Pursuit of Justice. Até o 20 suas curas são Holy Light, Lay on Hands e Blessing of Protection: nas missões sozinho use Seal of Righteousness, Judgment e Holy Strike como um paladino de dano, sem desperdiçar mana.",
    ["e1a4083"] = "Com Flash of Light você tem duas curas: Holy Light é lenta e forte, para quando é preciso muita vida e há tempo; Flash of Light é rápida e custa menos, para dano pequeno e constante. Escolher a cura certa é todo o trabalho: a errada queima mana. A partir do 20 também Consecration, Exorcism e Blessing of Kings.",
    ["42143bb"] = "A partir do 22 os pontos vão para Holy: Spiritual Focus (os golpes que você sofre atrasam menos suas magias), depois Reverence (parte da regeneração de mana continua enquanto você lança) e Healing Light (mais cura para Holy Light, Flash of Light e Holy Shock).",
    ["a1c4391"] = "Como curar: se o tanque sofre dano constante use Flash of Light ou Holy Light; para dano repentino Holy Shock; em emergência Lay on Hands (gasta todo o seu mana). Blessing of Protection em um aliado que sofre dano físico, nunca no tanque: se ele ficar imune os inimigos se voltam para os outros.",
    ["e98c82f"] = "Illumination: uma cura crítica de Flash of Light, Holy Light ou Holy Shock pode devolver mana (metade do custo base), por isso Intelecto e crítico importam. A partir do 37 Oath of Light no alvo principal; a partir do 38 Infusion of Light: uma cura crítica de Holy Shock ou Flash of Light deixa seu próximo Holy Light mais rápido.",
    ["3bb92dd"] = "No 40 você tem a dupla especialização (mantenha Retribution como segunda spec para as missões sozinho) e armaduras de placas. A partir do 42 Holy Shock: uma cura instantânea com 10 segundos de recarga, ou dano sagrado em um inimigo. A partir do 45 Divine Favor: sua próxima cura é sempre crítica (2 minutos de recarga), para quando o tanque está em perigo. A partir do 47 Holy Power torna mais prováveis os críticos de Holy Shock e Holy Strike.",
    ["31364c3"] = "Light's Vigil: um efeito de 30 segundos em um aliado; um Holy Shock no mesmo alvo o ativa, cura também o grupo e não inicia a recarga do Holy Shock. Custa muito e só pode haver um por grupo: guarde-o para dano em vários jogadores. Em um inimigo devolve 75% do mana. Os últimos pontos (a partir do 56) vão para Divine Intellect.",
    ["7fda0df"] = "Para Holy, primeiro vem o poder de cura, depois o Intelecto (mais mana e mais críticos, que devolvem mana via Illumination), depois o mana a cada 5 segundos e o Espírito (com Reverence parte da regeneração continua enquanto você lança). A arma vale pelos atributos, não pelo dano: uma maça com cura e Espírito vence uma arma com mais DPS. Malha até o 40, depois placas, mas uma peça de tecido com os atributos certos vale mais que uma de malha sem eles.",
    ["a531e3f"] = "Seal of Fury é o selo do tank: cada golpe causa dano sagrado extra e com o escudo você ganha uma absorção igual à metade desse dano. O Judgment dele faz você provocar por 3 segundos a 10 metros. Righteous Fury aumenta toda a sua ameaça em 33%. A partir do 22 você passa para a árvore Protection, depois de Pursuit of Justice.",
    ["8279baa"] = "Blessing of Kings, Retribution Aura e Righteous Fury ativo. Mantenha sempre Seal of Fury. Julgue enquanto corre para o monstro para provocar. Coloque Consecration assim que estiver em corpo a corpo, se o mana permitir. Depois Holy Strike a cada recarga e Exorcism em mortos-vivos e demônios. Reúna até quatro inimigos e queime tudo com Consecration.",
    ["34e2900"] = "Shield Specialization: um bloqueio devolve 4% do mana máximo, no máximo a cada 3 segundos: é grande parte do seu mana.",
    ["cc3ac76"] = "Templar's Bulwark: um escudo que absorve dano igual a toda a sua vida por 8 segundos, mas dá a você Forbearance por um minuto. A partir do 37 Swift Judgement: o Judgment do selo dispara sozinho com 1 minuto de recarga, então você tem uma segunda provocação.",
    ["be55413"] = "Holy Shield: por 10 segundos você bloqueia mais vezes e até 4 bloqueios causam dano sagrado. Reckoning (a partir do 43) pode dar um ataque extra depois de um bloqueio ou de um crítico sofrido.",
    ["e76d8e9"] = "Para Protection o poder mágico vem primeiro (Seal of Fury, Holy Shield e Consecration causam dano sagrado), depois Força e Vigor. Para a arma é melhor uma mais rápida: Seal of Fury bate a cada golpe. Uma arma com poder mágico pode valer um pouco menos de dano.",
    ["05e5db7"] = "Shadow Word: Pain; missão de classe curta (uma túnica)",
    ["c95888a"] = "Mind Blast, Resurrection; a missão de raça ensina a primeira habilidade só da sua raça",
    ["091c0cd"] = "Holy Fire, Flash Heal, Devouring Plague, Fear Ward, Mind Soothe, Shackle Undead; a segunda habilidade racial",
    ["71b2a72"] = "Fortitude em você antes do pull. Abra com Smite, ponha Shadow Word: Pain no alvo e termine com a varinha, que não custa mana e no início causa grande parte do seu dano (fique parado meio segundo antes de usá-la). Se o monstro alcançar você, primeiro Power Word: Shield. O mais importante é ter uma boa varinha: troque-a sempre que achar uma melhor.",
    ["e023128"] = "Mind Blast é o golpe forte com recarga curta. Os primeiros sete pontos de talento são iguais para todas as especializações: Wand Specialization (10-11) e Spirit Tap (12-16). Com Spirit Tap, cada morte de um monstro que dá experiência dobra o seu Espírito por 15 segundos e nesse tempo metade da regeneração de mana continua enquanto você lança: menos pausas para beber.",
    ["8df287d"] = "Inner Fire: armadura extra, cada golpe que você leva usa uma carga. Mantenha-o, junto com Fortitude, sempre em você e lance de novo quando acabar.",
    ["bebe913"] = "Psychic Scream faz os inimigos próximos fugirem, mas cuidado: eles podem trazer outros monstros de volta.",
    ["ffa87bf"] = "O mestre hoje ensina a você mais do que em qualquer outro nível: Holy Fire (abertura lenta mas forte, queima também ao longo do tempo), Flash Heal (rápido mas caro), Devouring Plague (dano ao longo do tempo que cura você) e outras.",
    ["084f80e"] = "Shadow é a especialização recomendada para subir sozinho: os pontos vão para Shadow Word: Pain, Mind Blast e Mind Flay, assim os monstros morrem mais cedo.",
    ["f33a503"] = "Ponha Shield em você se o monstro alcançar. Abra com Mind Blast, depois Shadow Word: Pain. A partir do 27 também Devouring Plague e Mind Flay, e depois de Shadow Word: Pain acrescente Vampiric Embrace para que o seu dano sombrio cure você. Depois termine com a varinha. Se o mana estiver baixo, pule Devouring Plague e Mind Flay.",
    ["496ef3d"] = "Shadow Word: Death é dano repentino, mas se o alvo sobreviver você sofre 30% da sua vida máxima: guarde-o para o golpe final.",
    ["edd0d02"] = "Shadowform: fique em Shadowform enquanto luta (+10% de dano sombrio, feitiços sombrios custam metade do mana, -15% de dano físico, mas você não pode lançar curas: saia antes de curar). Abra com Mind Blast, depois Shadow Word: Pain, Vampiric Embrace, Devouring Plague e Mind Flay. Quando mais um golpe mata o monstro: Shadow Word: Death, ou deixe o último pedaço para a varinha. Shield em você se o monstro alcançar.",
    ["b912dce"] = "Para Shadow vem primeiro o poder mágico (o sombrio também serve: quase todo o seu dano é sombrio), depois crítico e Acerto (Hit). A varinha é muito importante: no início causa grande parte do dano.",
    ["8e3f775"] = "Discipline é a especialização de cura que recomendamos para jogar sozinho: a partir do 20 Power in Light soma dano a Smite.",
    ["916c9c2"] = "Abra com Holy Fire de longe, Smite enquanto o monstro chega, depois Mind Blast, Shadow Word: Pain e a varinha. Se a luta for mal: Shield em você, depois cure: Flash Heal se precisar rápido, Heal se tiver tempo.",
    ["a80f7e5"] = "Penance: uma rajada de golpes sagrados que fere um inimigo ou cura um aliado, 12 segundos de recarga, o primeiro golpe sai na hora.",
    ["037a666"] = "Primeiro Shield em você. Abra com Holy Fire de longe. Smite enquanto o monstro anda, depois Penance no mesmo alvo porque Power in Light faz bater mais forte. Depois Mind Blast e Shadow Word: Pain. Para terminar Shadow Word: Death se um golpe mata, senão a varinha. Cada vez que Weakened Soul some você pode se proteger de novo.",
    ["9d0affc"] = "Power Infusion: +20% de dano e cura por 15 segundos, em você ou num amigo: lance em você logo antes de abrir, sempre que estiver pronta. No 60 Inner Focus para emergências: o feitiço seguinte é grátis.",
    ["8e7cd8d"] = "Para Discipline e Holy procure poder de cura e regeneração de mana, depois Intelecto e Espírito. Escolha a arma com esses mesmos atributos: não importa se é um cajado ou uma de uma mão com mão secundária.",
    ["c5c1351"] = "Ponha Shield e Renew em você antes do pull. Depois abra com Holy Fire, Smite enquanto o monstro chega, Mind Blast e Shadow Word: Pain. Termine com Shadow Word: Death se matar ou com a varinha.",
    ["575bdd0"] = "Holy Nova fere todo inimigo próximo e cura o grupo: custa muito mana, então use com vários inimigos em cima, ou quando é grátis (Searing Light a partir do 43: Holy Fire pode tornar grátis a próxima Holy Nova).",
    ["6953353"] = "Antes do pull ponha em você Shield, Renew e Prayer of Mending (cura na próxima vez que o alvo levar dano e depois salta para outro do grupo, 10 segundos de recarga).",
    ["a5c9096"] = "Para Holy procure poder de cura e regeneração de mana, depois Intelecto e Espírito. Escolha a arma com esses mesmos atributos.",
    ["aa71e89"] = "Backstab (precisa de uma adaga, só pelas costas), Pick Pocket",
    ["2e3c463"] = "Slice and Dice, Sprint, Sap; missão de classe (Blade of Cunning)",
    ["3a2246d"] = "Ambush (precisa de uma adaga), Poised (passiva)",
    ["8abd601"] = "Rupture; missão dos venenos: Instant Poison e Crippling Poison",
    ["6c840ea"] = "Shank (nova no Forever)",
    ["f3d428e"] = "Mutilate (talento Assassination)",
    ["3e307c7"] = "Death Mark (talento Subtlety), Slice and Dice posto 2",
    ["f14c847"] = "Shank posto 2",
    ["a554ba3"] = "Ande até o monstro e use Sinister Strike enquanto tiver pontos de combo, depois Eviscerate: mais pontos, golpe mais forte. Stealth por ora pode ficar na barra. Se a luta piorar: Evasion e Gouge para interromper um lançamento ou ganhar alguns segundos.",
    ["44b2b7e"] = "Slice and Dice (um finalizador: você ataca 20% mais rápido, por mais tempo com mais pontos), Sprint (50% mais rápido por 15 segundos, não quebra Stealth) e Sap para tirar um humanoide da luta antes de começar.",
    ["665b56f"] = "Rupture: um sangramento mais longo com mais pontos. Com a missão dos venenos, Instant Poison e Crippling Poison.",
    ["d06b2e0"] = "Shank: um golpe da mão secundária que não pode errar; o primeiro posto custa 5 de energia, devolve 15 e recarrega em 10 segundos. A partir do 26 Cheap Shot do furtivo: atordoa por 4 segundos e dá 2 pontos.",
    ["6974c7f"] = "Combat é o duelista: luta em corpo a corpo com a arma que preferir, funciona com qualquer arma e não precisa de furtividade para começar. É a recomendada para subir sozinho.",
    ["cea5a19"] = "Riposte: depois de um aparo seu ela acende e bate por uma vez e meia o dano da arma, desarma o monstro por 6 segundos e custa só 10 de energia com 6 segundos de recarga.",
    ["5288c4d"] = "Instant Poison nas duas armas. Cheap Shot do furtivo para uma luta dura, senão Sinister Strike logo. Riposte logo depois de um aparo. Sinister Strike para os pontos com Shank na recarga: os primeiros cinco pontos em Slice and Dice, os cinco seguintes em Eviscerate.",
    ["869d1bf"] = "Com dois monstros em cima: Blade Flurry (a cada 2 minutos, por 15 segundos você ataca 20% mais rápido e cada golpe atinge também um segundo próximo).",
    ["9fb5eb8"] = "Adrenaline Rush (a cada 5 minutos: a energia volta o dobro mais rápido por 15 segundos) para um monstro perigoso.",
    ["f8cc28b"] = "Cold Blood logo antes de um Eviscerate grande.",
    ["625324b"] = "Armadura de couro com Agilidade: é a que você quer. Acerto (Hit), crítico, poder de ataque e Vigor são úteis. Combat pode usar qualquer tipo de arma, porque Hack and Slash dá um bônus para cada uma: espadas e machados, adagas e armas de punho, maças.",
    ["d01cb25"] = "Assassination é o envenenador: venenos e finalizadores ficam cada vez mais fortes, e no 40 chega Mutilate.",
    ["9eb3d72"] = "Instant Poison nas duas armas. Do furtivo abra com Garrote ou Cheap Shot. Sinister Strike para os pontos e Shank na recarga. Slice and Dice, depois Eviscerate; guarde Cold Blood para um Eviscerate grande.",
    ["33aceb3"] = "Venom: por 6 segundos depois de cada Shank os seus venenos batem 30% mais forte e 20% mais vezes. Shank na recarga.",
    ["88ede56"] = "Mutilate constrói os pontos: bate com as duas armas, 20% mais forte num alvo envenenado, e dá 2 pontos. São necessárias duas adagas. Slice and Dice, Shank na recarga para Venom, depois Eviscerate; Cold Blood num Eviscerate grande.",
    ["20500ff"] = "Armadura de couro com Agilidade. Assassination precisa de adagas para Backstab, Ambush e Mutilate. Acerto (Hit), crítico, poder de ataque e Vigor são úteis.",
    ["5259278"] = "Subtlety é o emboscador: abre cada luta das sombras com uma adaga na mão.",
    ["64f4a07"] = "Adaga na mão principal, Instant Poison nas duas armas. Chegue por trás do monstro, Premeditation, depois Ambush, depois Ghostly Strike, depois Garrote. Sinister Strike constrói o resto; Shank na recarga para a energia; Eviscerate fecha.",
    ["37c1365"] = "Hemorrhage constrói os pontos no lugar de Sinister Strike.",
    ["c0f22d5"] = "Hemorrhage e Shank constroem os pontos, e com Boot Knife cada Shank vale dois. Death Mark guarda dano por 6 segundos: gaste nele um conjunto completo de pontos quando o monstro viver o bastante, depois Eviscerate para fechar. Se a luta for mal, Preparation zera Premeditation, Ghostly Strike e as suas outras recargas.",
    ["a993dd2"] = "Armadura de couro com Agilidade. Subtlety mantém uma adaga na mão principal (Ambush e Backstab a exigem). Acerto (Hit), crítico, poder de ataque e Vigor são úteis.",
    ["abbb551"] = "Earth Shock; missão do totem da terra: Stoneskin Totem",
    ["8e8845b"] = "Missão do totem do fogo: Searing Totem",
    ["2be8a5e"] = "Ghost Wolf, Frost Shock, Lesser Healing Wave, Frostbrand Weapon, Healing Stream Totem (missão do totem da água), Call of the Elements, Totemic Recall",
    ["0a8c77d"] = "Windfury Weapon, Reincarnation (precisa de um Ankh), Astral Recall, Grounding Totem",
    ["47fd721"] = "Chain Lightning, Windfury Totem; missão do totem do ar (as armas da tempestade)",
    ["b821239"] = "Chain Heal, armadura de malha",
    ["d6b5209"] = "Rockbiter Weapon fica na arma e a partir do 8 Lightning Shield entra antes do pull. Abra com Lightning Bolt e assim que chegar Earth Shock, que é instantâneo; contra um conjurador guarde o choque para interromper o lançamento dele. Quando o monstro estiver em cima, os golpes de corpo a corpo terminam. Se chegar outro monstro ponha Earthbind Totem: ele o desacelera e deixa você fazer kiting. No fim da luta Healing Wave se estiver ferido.",
    ["fa734a3"] = "Cada especialização tem um papel claro: Enhancement luta em corpo a corpo com uma arma grande, totens e choques; Elemental fica à distância com Lightning Bolt, Chain Lightning e Fire Nova; Restoration cura e fica em grupo ou em masmorras, não sozinho fazendo missões. Se acabar o mana Enhancement continua batendo (a morte demora mais), Elemental sofre mais.",
    ["b74be3c"] = "Flame Shock bate na hora com fogo e depois queima por 12 segundos. Flametongue Weapon soma dano de fogo a cada golpe; Searing Totem é uma pequena torre que atira num inimigo próximo.",
    ["35c7293"] = "Enhancement é a especialização que recomendamos para missões. Tem os seus pontos fracos: uma arma ruim baixa muito o dano, os custos de mana no início pesam e contra muitos inimigos ao mesmo tempo ela sofre.",
    ["028a6b7"] = "Stormstrike bate na hora com todo o dano da arma a cada 8 segundos, e o alvo sofre 20% a mais do seu próximo Lightning Bolt, Chain Lightning ou Earth Shock.",
    ["a94041d"] = "Stormstrike sempre que estiver pronto, e logo depois Earth Shock (o golpe de Stormstrike torna o choque mais forte). Rockbiter Weapon sempre na arma e Lightning Shield em você. Antes do pull Strength of Earth e Mana Spring e, se o mana permitir, Searing Totem ou Magma Totem. Abra com Lightning Bolt posto 1 (o mais barato), depois os golpes normais fazem o resto. Fire Nova só se os monstros estiverem no raio do seu totem de fogo e você ainda tiver mana. Depois da morte Healing Wave, e beba se o mana estiver baixo.",
    ["18a8896"] = "Windfury Weapon na arma no lugar de Rockbiter: cada golpe tem 20% de chance de dar dois ataques a mais, é a peça grande de Enhancement. Se uma esquiva ou um aparo zerar Stormstrike, aperte de novo logo. Windfury Totem, com Grounding Totem no lugar contra conjuradores.",
    ["f3777c4"] = "Maelstrom Weapon: os seus golpes acumulam até 5 cargas e cada carga deixa o próximo Lightning Bolt mais rápido e mais barato: com 5 cargas lance Lightning Bolt no posto mais alto. A partir do 46 Water Shield toma o lugar de Lightning Shield (só se pode ter um).",
    ["022a55d"] = "Para Enhancement a arma conta antes de tudo: o ideal é uma de duas mãos lenta, entre 3,3 e 3,8 de velocidade. Depois Força e poder de ataque, com o Intelecto logo atrás, porque alimenta Mental Dexterity e o mana.",
    ["4540d89"] = "Earthbound: quando você coloca Earthbind Totem os inimigos próximos ficam presos por 5 segundos.",
    ["bcd1d77"] = "Antes do pull Mana Spring Totem e um totem de fogo (Searing contra um monstro, Magma contra vários), Lightning Shield em você. Abra no limite do alcance com Lightning Bolt, ponha Flame Shock no alvo e continue com Lightning Bolt. Com três ou mais monstros Fire Nova sempre que estiver pronto. Earth Shock interrompe um conjurador e o traz até você. Earthbind Totem quando os monstros se aproximam. Cure-se e beba no fim.",
    ["13a3832"] = "Contra um monstro só: Searing Totem, abra de longe com Lightning Bolt, Flame Shock, continue com Lightning Bolt. Contra três ou mais: Magma Totem, abra com Chain Lightning, Flame Shock em um deles, depois Chain Lightning e Fire Nova a cada recarga com Lightning Bolt no meio.",
    ["2c3ba7a"] = "Lightning Mastery (15 segundos, depois 3 minutos): por 15 segundos Lightning Bolt é lançado mais rápido e Chain Lightning ignora a recarga. Use num elite ou num pull grande, senão a cada recarga.",
    ["b56c9ed"] = "Water Shield toma o lugar de Lightning Shield em você.",
    ["4688073"] = "Para Elemental procure poder mágico, com o Intelecto sobretudo para o mana. A partir do nível 40 você pode usar malha.",
    ["b4ca62b"] = "Antes do pull Water Shield, Mana Spring Totem e os totens que o grupo pode usar. Enquanto alguém leva dano, Healing Wave é o burro de carga. Lesser Healing Wave lança em 1,5 segundo e cura menos pelo mana: guarde-a para os momentos em que o tempo conta. Mana Tide Totem (12 segundos, 5 minutos de recarga) quando o grupo todo está sem mana. Quando ninguém está em perigo acrescente dano: Lightning Bolt num alvo, Fire Nova num grupo. Beba no fim.",
    ["42937c0"] = "Nature's Swiftness (a cada 3 minutos): o seu próximo feitiço de natureza é instantâneo, então uma Healing Wave instantânea para um amigo prestes a morrer. Windfury Totem se houver jogadores em corpo a corpo.",
    ["9b2d19c"] = "Riptide: cura ao longo do tempo com 12 segundos de recarga, e uma Chain Heal lançada justamente no alvo de Riptide é 25% mais forte. Chain Heal cura o alvo e outros dois aliados, então cobre o dano espalhado pelo grupo.",
    ["a86408d"] = "Para Restoration procure poder de cura, com o Intelecto sobretudo para o mana. A partir do nível 40 você pode usar malha.",
    ["c86a1be"] = "Voidwalker (missão de classe), Drain Soul, Healthstone",
    ["40cb6b4"] = "Succubus e Incubus (missões de classe), Demon Armor, Curse of the Elements, Rain of Fire, Ritual of Summoning",
    ["df7bfa2"] = "Felhunter (missão de classe), Hellfire",
    ["19e5308"] = "Howl of Terror, Felsteed (missão)",
    ["1c5b068"] = "O demônio entra primeiro, depois Bane of Agony e Corruption; só os monstros mais duros recebem Immolate, porque o demônio os segura. A ordem importa porque o dano atrai atenção: os primeiros ticks de Agony são pequenos, então o demônio segura o monstro até que um Immolate novo bata forte o bastante para fazê-lo virar para você. Mantenha Demon Skin, pule os DOTs num monstro quase morto e não renove Agony enquanto ele ainda estiver causando dano. Enquanto você não tem varinha, Shadow Bolt termina o trabalho; depois pegue uma varinha: cada tiro é mana poupado para o pull seguinte.",
    ["ea42414"] = "Drain Soul é a sua fonte principal de Soul Shards: um monstro não trivial que morre com o drain dele sempre dá um. Quando tiver poucos, termine as mortes com ele. Healthstone, Soul Stone e as invocações de Voidwalker, Succubus e Felhunter exigem fragmentos.",
    ["72f97d5"] = "Drain Life muda como você lê a tela: se a barra azul está baixa e a sua vida está boa, Life Tap; se a sua vida caiu de verdade, Drain Life no monstro. Assim quase todo o tempo morto some.",
    ["51205f3"] = "Demon Armor no lugar de Demon Skin. Com Ritual of Summoning você e dois companheiros trazem um membro do grupo que ainda está longe. Um Fear dá a você alguns segundos grátis para uma bandagem.",
    ["9d83c05"] = "Se você joga sozinho, Affliction é a escolha: a precisão e uma Corruption instantânea chegam cedo. Curse of the Elements vai ao lado de Agony. A partir do 25 Nightfall pode disparar com o dano de Corruption, Drain Life ou Drain Soul, e o Shadow Bolt depois do proc não tem tempo de lançamento. Você pode pegar o talento dos drains um pouco antes do 30 e se apoiar em Drain Life em cada luta.",
    ["04f03c2"] = "Siphon Life: um tick a cada 3 segundos por 30 segundos, então um monstro que morre em 10 leva só um terço. Guarde para lutas longas.",
    ["703c37f"] = "Demonic Sacrifice: você sacrifica o Felhunter e por duas horas recupera 3% da sua vida total a cada 4 segundos; invocar um demônio anula, então daqui em diante você faz missões quase sem pet.",
    ["2dbcea6"] = "Wrack: você canaliza por 6 segundos, causa dano sombrio, e os seus outros DOTs sombrios nesse alvo batem 10% mais forte enquanto durar.",
    ["edb7e47"] = "Escolha armas com poder mágico, porque você quase nunca as usará para bater. No início um upgrade de varinha supera quase todos os outros; depois, o poder mágico vem primeiro. O Vigor é vida extra para transformar em mana com Life Tap, o Intelecto uma reserva de mana maior, o Espírito rende mais a cada Life Tap.",
    ["1c3a6a3"] = "Se você prefere ver o demônio trabalhar, Demonology: com Demonic Brand a partir do 25. A partir do 25 Searing Pain coloca uma marca no alvo por 10 segundos, e no máximo os primeiros seis golpes do seu demônio causam dano extra: renove com um Searing Pain rápido no que o demônio está lutando e preencha os vazios com DOTs e a varinha.",
    ["00d4a86"] = "Soul Link: 30% de cada golpe direto em você vai para o demônio, e vocês dois causam 3% mais dano. Perde-se quando você troca de demônio: lance de novo toda vez.",
    ["a3cee7a"] = "Demonic Pact: o sacrifício sobrevive à troca de demônio, a menos que você invoque justamente o que sacrificou. Numa masmorra sacrifique o Imp (15% mais dano sombrio); em missões solo o Felhunter pelas curas dele, e lute ao lado de um Voidwalker, Succubus ou Incubus. A partir do 27 você também pode subir como Affliction e trocar de especialização: tem os pontos para os três postos de Demonic Brand.",
    ["545f2c9"] = "Destruction é jogável a partir do 10, mas fica muito mais forte no 39 e no 40, e fica mais tempo parada lançando que as outras duas: dá para escolhê-la também depois.",
    ["0b5d29c"] = "Shadowburn: um golpe instantâneo que custa um Shard e o devolve se um alvo não trivial morrer em 8 segundos.",
    ["124afde"] = "A abertura muda: Shadow Bolt da distância máxima e Immolate enquanto o raio ainda está no ar. Assim o monstro vem até você e não até o demônio, então escolha lutas que você possa encerrar rápido. Shadowburn termina os monstros; Conflagrate é melhor guardar para o fim do seu Immolate.",
    ["07ea333"] = "Com Shadow and Flame, Conflagrate aumenta o seu dano sombrio em 20% e Shadowburn o seu dano de fogo em 20%; Conflagrate não consome mais Immolate e Shadowburn devolve sempre o Shard. A partir do 39 não há motivo para segurá-los.",
    ["609f38c"] = "Incinerate faz 25% a mais em tudo que já está queimando por causa do seu Immolate.",
    ["a1d5005"] = "Defensive Stance, Taunt, Sunder Armor (missão de classe), Bloodrage",
    ["b87bfb2"] = "Revenge, Demoralizing Shout, Tactical Mastery (aprende-se com o mestre)",
    ["a61955b"] = "Victory Rush, Cleave, Slam, Retaliation; você pode usar duas armas",
    ["323f468"] = "Berserker Stance, Berserker Rage, Intercept (missão de classe)",
    ["b289adb"] = "Armadura de placas e montaria",
    ["2debde0"] = "Battle Shout antes do pull, Charge, Rend no que vive muito, depois deixe os golpes normais acumularem raiva. Heroic Strike só com raiva de que você não precisa: substitui um golpe normal e esse golpe não dá raiva. Com vários monstros Thunder Clap; não gaste raiva num monstro prestes a morrer.",
    ["f98c5d6"] = "Bloodrage entre um pull e outro: custa um pouco de vida e dá 10 de raiva na hora e 10 em 10 segundos. Nunca comece uma luta sem raiva.",
    ["970305a"] = "Victory Rush sempre que acender: depois de uma morte que dá experiência você tem 20 segundos, causa dano e cura você em 10%, 30 segundos de recarga e não custa raiva.",
    ["a60b4a3"] = "A partir do 14 Revenge é o seu ataque principal: use sempre que acender (depois de um bloqueio, uma esquiva ou um aparo). Passe para escudo e arma de uma mão. Thunder Clap e Demoralizing Shout em grupos.",
    ["41fd2f0"] = "Charge, depois fique em Defensive Stance. Mantenha Shield Block contra quem bate em você em corpo a corpo, e pule Shield Block contra conjuradores. Revenge sempre que acender; Rend e alguns Sunder Armor em monstros que vivem muito; Thunder Clap e Demoralizing Shout em grupos.",
    ["b604238"] = "Com Vanguard você pode usar Charge de Defensive Stance: pode abrir um pull sem trocar de postura, se estiver fora de combate.",
    ["c9e7c22"] = "Shield Wall: 60% menos dano por 12 segundos, para pulls que dão errado.",
    ["3f0c2f4"] = "Shield Slam é o golpe mais forte (o dano cresce com o seu valor de bloqueio): use primeiro e Revenge logo depois. Se tiver pouca raiva, Revenge primeiro, custa menos.",
    ["846367b"] = "Protection quer sobretudo Força (cada ponto dá 2 de poder de ataque e valor de bloqueio). Para a arma pegue o melhor DPS: Revenge e Shield Slam não dependem da arma. A Agilidade conta menos: dá crítico, esquiva e armadura mas nenhum poder de ataque.",
    ["fabdcb6"] = "Rend primeiro, depois Overpower sempre que acender (depois de uma esquiva do alvo).",
    ["f29cf52"] = "Rend, depois Overpower quando acender. A partir do 20 Slam logo depois de um golpe.",
    ["60998aa"] = "Sweeping Strikes: os seus próximos cinco golpes atingem também um segundo inimigo próximo, é um grande salto. Comece num monstro enquanto tiver raiva extra, depois puxe um segundo monstro e use Sweeping Strikes e Cleave nos dois.",
    ["efc030d"] = "Com Bloodthrill, se Rend estiver no alvo os golpes da mão principal têm 20% de chance de disparar Overpower: Rend fica na rotação até o 60.",
    ["98a8fec"] = "Mortal Strike é o seu novo ataque principal.",
    ["7caf705"] = "A arma conta mais que tudo: procure o DPS mais alto, e para Arms uma de duas mãos lenta (cada golpe e Mortal Strike e Slam causam mais dano). No resto primeiro Acerto (Hit, porque um golpe errado não dá nem dano nem raiva), depois Força e Crítico. A Agilidade dá crítico e esquiva mas nenhum poder de ataque.",
    ["ce62f29"] = "Rend em monstros que vivem muito, Overpower quando o alvo esquiva. Se um segundo monstro estiver ao lado do alvo, gaste a raiva extra em Cleave. Escolha uma mão secundária rápida: mais golpes, mais raiva.",
    ["1879df1"] = "Death Wish: por 30 segundos você causa 20% mais dano físico e não pode ser amedrontado, mas sofre 5% mais dano. Reckless Swings (31): custa um pouco de vida e os próximos quatro golpes dão 5 de raiva a mais cada.",
    ["0d27ce4"] = "Com Whirlwind (nível 36) é a sua tecla principal, mesmo contra um monstro só: a recarga cai para 8 segundos e atinge o mais próximo com 30% a mais de dano.",
    ["308a3c5"] = "Bloodthirst sempre que Whirlwind estiver em recarga. A partir do 50 você tem Recklessness.",
    ["2d76abd"] = "A arma conta mais que tudo: procure o DPS mais alto. Para a mão secundária uma rápida (mais golpes, mais raiva). No resto primeiro Acerto (Hit), depois Força e Crítico. A Agilidade dá crítico e esquiva mas nenhum poder de ataque.",
}
